// Method: SpriteFrames::get_frame_texture
static JSValue js_SpriteFrames_get_frame_texture(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "SpriteFrames.get_frame_texture: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "SpriteFrames.get_frame_texture: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }


    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "SpriteFrames.get_frame_texture: invalid or freed object");
    }

    SpriteFrames* typed_obj = Object::cast_to<SpriteFrames>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "SpriteFrames.get_frame_texture: object is not a SpriteFrames");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 3) {
        return JS_ThrowTypeError(ctx, "SpriteFrames.get_frame_texture: expected at least 2 arguments, got %d", argc - 1);
    }

    // Convert arguments
    const char* cstr_anim = JS_ToCString(ctx, argv[1]); StringName arg_anim = cstr_anim ? String::utf8(cstr_anim) : ""; JS_FreeCString(ctx, cstr_anim);
    int64_t arg_idx; JS_ToInt64(ctx, &arg_idx, argv[2]);

    Ref<Texture2D> result = typed_obj->get_frame_texture(arg_anim, arg_idx);
    if (result.is_null()) return JS_NULL;
    Object* ret_obj_ptr = result.ptr();
    int64_t ret_handle = qjs_ctx->get_object_registry()->get_or_create_handle(ret_obj_ptr);
    // Store class name in local String to avoid dangling pointer from temporary
    String ret_class_str = ret_obj_ptr->get_class();
    CharString ret_class_utf8 = ret_class_str.utf8();
    const char* ret_class_name = ret_class_utf8.get_data();
    // Use __wrap_existing_godot_object to create a proper Proxy with method/property access
    JSValue global = JS_GetGlobalObject(ctx);
    JSValue wrap_fn = JS_GetPropertyStr(ctx, global, "__wrap_existing_godot_object");
    if (JS_IsFunction(ctx, wrap_fn)) {
        JSValue args[2] = { JS_NewInt64(ctx, ret_handle), JS_NewString(ctx, ret_class_name) };
        JSValue wrapped = JS_Call(ctx, wrap_fn, JS_UNDEFINED, 2, args);
        JS_FreeValue(ctx, args[0]);
        JS_FreeValue(ctx, args[1]);
        JS_FreeValue(ctx, wrap_fn);
        JS_FreeValue(ctx, global);
        return wrapped;
    }
    JS_FreeValue(ctx, wrap_fn);
    JS_FreeValue(ctx, global);
    // Fallback: return raw object
    JSValue ret_obj = JS_NewObject(ctx);
    JS_SetPropertyStr(ctx, ret_obj, "__handle", JS_NewInt64(ctx, ret_handle));
    JS_SetPropertyStr(ctx, ret_obj, "__class", JS_NewString(ctx, ret_class_name));
    return ret_obj;
}

